def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def get_pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return [value[0], value[1]]
        return [default[0], default[1]]

    def best_by_distance(points, origin, maximize=False):
        pts = []
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                pts.append([p[0], p[1]])
        if not pts:
            return None
        if maximize:
            return max(pts, key=lambda p: manhattan(p, origin))
        return min(pts, key=lambda p: manhattan(p, origin))

    env = observation.get("environment_name", "resource_collection")
    self_pos = get_pos(observation.get("self_position", [0, 0]))
    opp_pos = get_pos(observation.get("opponent_position", self_pos))
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [
            [0, 0],
            [0, max(0, grid_h - 1)],
            [max(0, grid_w - 1), 0],
            [max(0, grid_w - 1), max(0, grid_h - 1)],
        ]
        target = best_by_distance(corners, opp_pos, maximize=True)
        return step_toward(self_pos, target if target is not None else [0, 0])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        target = best_by_distance(targets, self_pos, maximize=False)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources")
    if isinstance(resources, dict):
        resources = resources.get("positions") or resources.get("cells") or resources.get("items") or []
    target = best_by_distance(resources, self_pos, maximize=False)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallback: approach opponent in competitive modes, otherwise stay put.
    if opp_pos != self_pos:
        return step_toward(self_pos, opp_pos)
    return [0, 0]

